    "content": "当地时间10月11日，高盛将12月布伦特原油价格预测上调5美元至每桶90美元，理由是中东地区供应风险上升。该行维持2027年布伦特原油均价预测不变，仍为每桶80美元。高盛分析师表示，中东供应逐步调整最终可能推动油价回落，但地区局势若再度升级，仍将带来显著的上行风险。波斯湾原油出口量（包括非公开运输的原油）已恢复至2025年平均水平，全球石油市场9月大致处于供需平衡状态。不过，供应风险、库存偏低、实物补库需求及金融对冲需求仍支撑油价。（界面）"
