    "description": "记者昨天从退役军人事务部了解到，新修订的《烈士纪念设施保护管理办法》将于今年11月1日起正式施行。新规补齐零散烈士设施管护短板，规范建设行为，同时细化展陈、祭扫、寻亲等内容，让烈士纪念设施得到更全面规范的保护。",
    "content": "记者昨天从退役军人事务部了解到，新修订的《烈士纪念设施保护管理办法》将于今年11月1日起正式施行。新规补齐零散烈士设施管护短板，规范建设行为，同时细化展陈、祭扫、寻亲等内容，让烈士纪念设施得到更全面规范的保护。"
