    "author": "",
    "description": "中新网10月12日电 据中央气象台网站消息，昨日，内蒙古中西部、青海大部等地已出现明显降温，降幅可达7~9℃。今明两天，内蒙古中东部、华北和东北地区将出现4～6℃降温，局地降幅可达8～12℃；上述地区还伴有4～5级风、阵风6～8级。受冷空气影响，西北地区东部、华北西部和南部、东北地区北部和东部等地有小到中雨或雨夹雪，其中山西、河北等局地有大雨或暴雨。",
