    "title": "“线易微电子”完成A轮融资，筑牢高压电力电子安全屏障",
    "link": "https://36kr.com/newsflashes/4019963990233216?f=rss",
    "pub_date": "2026-10-12 09:00:00",
    "author": "",
    "description": "近日，国内首家突破高可靠磁隔技术的高端模拟芯片公司——深圳线易微电子科技有限公司（下称“线易微电子”）正式宣布完成数千万元A轮融资，本轮融资由锡洲国际投资，IO资本担任财务顾问。募集资金将投向新品研发、市场渠道拓展、客户支持团队建设，加速在算力基础设施、具身智能等新兴赛道产品验证与客户导入。",
    "content": "近日，国内首家突破高可靠磁隔技术的高端模拟芯片公司——深圳线易微电子科技有限公司（下称“线易微电子”）正式宣布完成数千万元A轮融资，本轮融资由锡洲国际投资，IO资本担任财务顾问。募集资金将投向新品研发、市场渠道拓展、客户支持团队建设，加速在算力基础设施、具身智能等新兴赛道产品验证与客户导入。"
