    "description": "2026年10月12日 新华社北京10月11日电 全国政协主席王沪宁11日在京会见越南国会主席陈青敏。 王沪宁表示，近年来，习近平总书记、国家主席同苏林总书记、国家主席保持密切战略沟通，引领中越关系在世界百年变局中破浪前行。中方愿同越方遵循两党两国最高领导人战略指引，按照“六个更”总体目标，高质量推进各领域互利合作，推进中越命运共同体建设。中国全国政协愿同越方深化交流合作，为推动各自现代化事业作出贡献。 陈青敏表示，在两党两国最高领导人…",
    "content": "2026年10月12日 新华社北京10月11日电&nbsp;&nbsp;全国政协主席王沪宁11日在京会见越南国会主席陈青敏。 王沪宁表示，近年来，习近平总书记、国家主席同苏林总书记、国家主席保持密切战略沟通，引领中越关系在世界百年变局中破浪前行。中方愿同越方遵循两党两国最高领导人战略指引，按照“六个更”总体目标，高质量推进各领域互利合作，推进中越命运共同体建设。中国全国政协愿同越方深化交流合作，为推动各自现代化事业作出贡献。 陈青敏表示，在两党两国最高领导人战略引领下，越中关系持续深化，政治基础、物质基础、民心基础…"
