    "description": "2026年10月12日 10月11日，作为连接广东省珠海市与澳门特别行政区的重要民生通道，拱北—关闸口岸今年出入境人员突破1亿人次，比2025年提前14天。日益繁忙且便利化不断提升的拱北—关闸口岸是粤港澳大湾区“硬联通”“软联通”不断提速的缩影。图为珠海拱北口岸出境大厅，旅客有序通关。 本报记者 贺林平文 丁 瑞摄（人民视觉） 2026-10-12 00:00:00:0 30185060 10http://paper.people.co…",
