    "description": "2026年10月12日 （一） 什么是共产党？ “共产党就是自己有一条被子，也要剪下半条给老百姓的人。” 故事讲述者是湖南汝城县沙洲瑶族村的徐解秀老人。红军长征途中，3名女战士借宿老人家中，临走时，把仅有的一条被子剪下一半给老人留下了。 2016年10月，习近平总书记在纪念红军长征胜利80周年大会上的重要讲话中，深情讲述了“半条被子”的故事。 2020年9月，总书记在“半条被子”的故事发生地考察调研时指出：“故事充分体现了中国共产党的人…",
