    "description": "2026年10月12日 时间是生命的刻度，时间是奋进的标尺。 一条稳步上扬的“生命线”，浓缩了一部国民健康的“编年史”—— 新中国成立初期，我国人均预期寿命只有35岁。2015年我国人均预期寿命为76.34岁，2025年达到79.25岁，孕产妇死亡率和婴儿死亡率持续下降，主要健康指标稳居中高收入和人口过亿国家前列，人民健康水平显著提高。 一组举世瞩目的数据，标记着健康中国建设的历史性成就—— 我国建成世界上规模最大的医疗服务、传统医药、…",
    "content": "2026年10月12日 时间是生命的刻度，时间是奋进的标尺。 一条稳步上扬的“生命线”，浓缩了一部国民健康的“编年史”—— 新中国成立初期，我国人均预期寿命只有35岁。2015年我国人均预期寿命为76.34岁，2025年达到79.25岁，孕产妇死亡率和婴儿死亡率持续下降，主要健康指标稳居中高收入和人口过亿国家前列，人民健康水平显著提高。 一组举世瞩目的数据，标记着健康中国建设的历史性成就—— 我国建成世界上规模最大的医疗服务、传统医药、疾病预防控制和医疗保障体系；110万余个医疗卫生机构、1600多万名医疗卫生人员…"
