    "description": "2026年10月12日 本报北京10月11日电 （记者林丽鹂）记者从市场监管总局日前召开的“经营者集中简易案件审查制度成效”专题新闻发布会上获悉：简易案件审查制度创设于2014年，至今已实施了12年，简易案件平均审查时间从2014年的39.9天缩短至今年以来的18.6天，审查效率不断提升，大幅降低了企业投资并购的制度性交易成本。 反垄断法提出，要健全经营者集中分类分级审查制度，提高审查质量和效率。经营者集中简易案件审查制度是落实反垄断法…",
    "content": "2026年10月12日 本报北京10月11日电&nbsp;&nbsp;（记者林丽鹂）记者从市场监管总局日前召开的“经营者集中简易案件审查制度成效”专题新闻发布会上获悉：简易案件审查制度创设于2014年，至今已实施了12年，简易案件平均审查时间从2014年的39.9天缩短至今年以来的18.6天，审查效率不断提升，大幅降低了企业投资并购的制度性交易成本。 反垄断法提出，要健全经营者集中分类分级审查制度，提高审查质量和效率。经营者集中简易案件审查制度是落实反垄断法分类分级审查要求的重要举措，其核心是把不太可能产生竞争问题…"
