    "description": "2026年10月12日 本报深圳10月11日电 （记者程远州）深港间重要的24小时客运陆路口岸——皇岗口岸11日举行开通仪式，宣布将于12日正式通关，通关后实施“一地两检”安排及“合作查验、一次放行”全新通关模式，为旅客和客运车辆提供24小时通关服务。 即将重新开关的皇岗口岸是全国规模最大的单体口岸建筑，分为地下4层、地上5层，总建筑面积达68.97万平方米，也是全球最大的陆路口岸综合体，规划有5条轨道线交会。 皇岗口岸是推进粤港澳大湾…",
    "content": "2026年10月12日 本报深圳10月11日电&nbsp;&nbsp;（记者程远州）深港间重要的24小时客运陆路口岸——皇岗口岸11日举行开通仪式，宣布将于12日正式通关，通关后实施“一地两检”安排及“合作查验、一次放行”全新通关模式，为旅客和客运车辆提供24小时通关服务。 即将重新开关的皇岗口岸是全国规模最大的单体口岸建筑，分为地下4层、地上5层，总建筑面积达68.97万平方米，也是全球最大的陆路口岸综合体，规划有5条轨道线交会。 皇岗口岸是推进粤港澳大湾区建设、服务河套深港科技创新合作区的标志性工程，并被纳入国…"
