    "description": "2026年10月12日 2023年10月，习近平总书记对宣传思想文化工作作出重要指示，提出“七个着力”的重要要求，其中首要的是“着力加强党对宣传思想文化工作的领导”。宣传思想文化工作事关党的前途命运，事关国家长治久安，事关民族凝聚力和向心力。坚持和加强党对宣传思想文化工作的领导，是新时代文化建设取得重大成就的根本保证，是中国特色社会主义文化发展道路最本质的特征。《习近平文化文选》（以下简称《文选》）第一卷、第二卷收入习近平总书记关于文化…",
    "content": "2026年10月12日 2023年10月，习近平总书记对宣传思想文化工作作出重要指示，提出“七个着力”的重要要求，其中首要的是“着力加强党对宣传思想文化工作的领导”。宣传思想文化工作事关党的前途命运，事关国家长治久安，事关民族凝聚力和向心力。坚持和加强党对宣传思想文化工作的领导，是新时代文化建设取得重大成就的根本保证，是中国特色社会主义文化发展道路最本质的特征。《习近平文化文选》（以下简称《文选》）第一卷、第二卷收入习近平总书记关于文化建设最重要、最基本的著作共78篇，系统呈现了习近平文化思想的基本精神、基本内容、…"
