    "description": "2026年10月12日 习近平总书记指出：“中国将同各方携手推进重点领域合作，动员发展资源，深化全球减贫脱贫合作”。“十五五”规划纲要提出：“促进全球减贫合作”。中国成功打赢脱贫攻坚战，走出了一条中国特色减贫之路，为推进全球减贫进程、完善全球减贫治理体系提供了中国智慧、中国方案。今年5月，中国与53个国家、9个国际机构共同发起成立全球减贫与发展伙伴联盟（以下简称“联盟”）。面向未来，促进全球减贫合作走深走实，需要切实发挥联盟作用，提升分…",
    "content": "2026年10月12日 习近平总书记指出：“中国将同各方携手推进重点领域合作，动员发展资源，深化全球减贫脱贫合作”。“十五五”规划纲要提出：“促进全球减贫合作”。中国成功打赢脱贫攻坚战，走出了一条中国特色减贫之路，为推进全球减贫进程、完善全球减贫治理体系提供了中国智慧、中国方案。今年5月，中国与53个国家、9个国际机构共同发起成立全球减贫与发展伙伴联盟（以下简称“联盟”）。面向未来，促进全球减贫合作走深走实，需要切实发挥联盟作用，提升分享与合作效能，促进南南合作，更好将中国减贫经验转化为国际公共产品，携手各国探索符…"
