    "description": "2026年10月12日 秋高气爽，书香正浓。记者先后走进西安电子科技大学、陕西师范大学、西北工业大学、西安交通大学、延安大学、西北大学6所高校的图书馆，发现它们以各自的方式，将红色基因、科学家精神、传统文化等与青春成长紧紧编织在一起。 一馆一史，珍藏记忆 西安电子科技大学长安校区图书馆里，一场“电波不灭 长征有声”红色经典朗诵会正在进行。位于图书馆三楼的西军电文库是该馆的特藏库，主要收藏学校师生、校友的著作、手稿、教材、笔记等，以留存西…",
    "content": "2026年10月12日 秋高气爽，书香正浓。记者先后走进西安电子科技大学、陕西师范大学、西北工业大学、西安交通大学、延安大学、西北大学6所高校的图书馆，发现它们以各自的方式，将红色基因、科学家精神、传统文化等与青春成长紧紧编织在一起。 一馆一史，珍藏记忆 西安电子科技大学长安校区图书馆里，一场“电波不灭&nbsp;&nbsp;长征有声”红色经典朗诵会正在进行。位于图书馆三楼的西军电文库是该馆的特藏库，主要收藏学校师生、校友的著作、手稿、教材、笔记等，以留存西电的学术历史和办学传统。 特藏库最深处有两排石凳。西电图书…"
