    "content": "2026年10月12日 “编制社保在高校、创新创业在企业，欢迎各位有识之士来泰州合作创业！”9月，江苏省泰州市海陵区招才大使、泰州学院人工智能学院党总支副书记徐珊珊随海陵区招才引智团队来到西安电子科技大学，一口气对接多个科技人才项目，其中不少是海陵区主导产业与人工智能产业间的合作项目。 这是海陵区“百城千才高校行”系列活动的最新一站——该区正通过“一访多校”“一程多企”模式，持续回访合作项目以提升校企合作能级，回访重点院系以提升成果转化质效，回访实训平台以提升人才招引力度，全力推动校地合作由“单点对接”向“链式协同…"
