    "content": "2026年10月12日 本报北京10月11日电&nbsp;&nbsp;（记者蒋雪鸿）记者从国家气候中心获悉：一次东部型超强厄尔尼诺事件已于今年9月正式形成。 自今年5月以来，赤道中东太平洋进入厄尔尼诺状态，关键区海温持续攀升。7—9月，关键区海温指数滑动平均值超过2.5摄氏度，达超强事件标准。9月，赤道太平洋大部海表温度较常年同期偏高，东太平洋暖水中心偏高3.0摄氏度以上，关键区海温指数为2.94摄氏度，较8月上升0.35摄氏度。7—9月，关键区海温指数平均值为2.54摄氏度。 国家气候中心主要对特定区域海温指数进…"
