    "content": "2026年10月12日 不久前，俄罗斯远东哈巴罗夫斯克边疆区首府哈巴罗夫斯克市落成一座纪念战胜军国主义日本的纪念碑。揭幕一个多月来，多所学校将其纳入秋季爱国主义研学路线。该纪念碑已成为当地纪念二战胜利的知名打卡点。 这座雕塑以苏联红军士兵手持长枪、将绘有菊花图案的日本军国主义时期界碑砸成两半为造型，定格了世界反法西斯战争胜利的历史瞬间，是俄罗斯迄今为止规模最大的同类主题纪念碑。面对这座历史纪念碑，日方反应强烈。揭幕前一日，日本驻哈巴罗夫斯克总领事馆便紧急交涉，要求移除界碑上代表日本皇室的菊花图案；日本首相高市早苗更…"
