    "description": "2026年10月12日 联合国近日发布的《2026年全球风险报告》显示，当前全球各类风险相互交织、相互叠加，全球风险格局更趋复杂，任何单一主体都难以独自应对。报告强调，各国政府加强协调行动仍是应对全球风险的最有效方式，国际社会应加强多边合作，携手应对多重风险交织叠加带来的挑战。 这是联合国继2024年首次开展全球风险调查后发布的第二份同类报告。本次调查于今年2月至4月进行，收集了来自各国政府、国际组织、私营部门、民间社会和学术界1300…",
    "content": "2026年10月12日 联合国近日发布的《2026年全球风险报告》显示，当前全球各类风险相互交织、相互叠加，全球风险格局更趋复杂，任何单一主体都难以独自应对。报告强调，各国政府加强协调行动仍是应对全球风险的最有效方式，国际社会应加强多边合作，携手应对多重风险交织叠加带来的挑战。 这是联合国继2024年首次开展全球风险调查后发布的第二份同类报告。本次调查于今年2月至4月进行，收集了来自各国政府、国际组织、私营部门、民间社会和学术界1300余名人士的观点，覆盖全球各个地区。受访者对政治、经济、环境、社会和技术5个领域的…"
