    "description": "2026年10月12日 10月1日出版的《求是》杂志发表习近平总书记的重要文章《加强普惠性、基础性、兜底性民生建设》。文章强调，发展经济的根本目的是更好保障和改善民生，抓民生也是抓发展。这一重要论断，深刻揭示了经济发展与民生建设辩证统一的内在机理，破除了将民生简单视作财政负担的片面认识，为中国式现代化进程中统筹推进经济增长与民生保障提供了根本遵循。 我们的目标很宏伟，也很朴素，归根到底就是让老百姓过上更好的日子。中国的经济治理有两层基本…",
    "content": "2026年10月12日 10月1日出版的《求是》杂志发表习近平总书记的重要文章《加强普惠性、基础性、兜底性民生建设》。文章强调，发展经济的根本目的是更好保障和改善民生，抓民生也是抓发展。这一重要论断，深刻揭示了经济发展与民生建设辩证统一的内在机理，破除了将民生简单视作财政负担的片面认识，为中国式现代化进程中统筹推进经济增长与民生保障提供了根本遵循。 我们的目标很宏伟，也很朴素，归根到底就是让老百姓过上更好的日子。中国的经济治理有两层基本逻辑：第一层逻辑，经济发展是保障和改善民生的物质基础，没有持续健康的发展，做大社…"
