    "description": "近年来，一些人员非法破解无人机飞行控制系统，解除无人机禁飞区、限飞区、飞行高度等安全限制，实施“黑飞”行为，严重扰乱空中秩序，给公共安全和国家安全带来重大安全隐患。公安机关网安部门围绕无人机“黑飞”行为，特别是对非法破解无人机飞行控制系统的黑客行为，始终保持严打高压态势。",
