    "description": "新华社快讯：10月12日6时30分，重建后的皇岗口岸正式开通，实施“一地两检”安排及“合作查验、一次放行”全新通关模式，旅客出入境更加便利。",
    "content": "新华社快讯：10月12日6时30分，重建后的皇岗口岸正式开通，实施“一地两检”安排及“合作查验、一次放行”全新通关模式，旅客出入境更加便利。"
