    "content": "新华社德黑兰10月11日电（记者沙达提）伊朗最高国家安全委员会秘书穆赫辛·雷扎伊11日表示，美国已接受伊朗就重新开放霍尔木兹海峡所提出的部分条件，但就伊朗提出的其他条件，目前情况尚不明朗。 在伊朗新闻电视台11日播放的采访中，雷扎伊作出上述表态并详细阐述了伊美近期沟通情况。 雷扎伊说：“过去两个月里，美方通过巴基斯坦、卡塔尔、伊拉克三个不同渠道，要求伊朗提出提议。伊朗向美方提出7项条件，并明确告知美方，除非满足这些条件，否则不会向其开放霍尔木兹海峡，也不会进行任何谈判。” 雷扎伊说，美方现已作出回应，“但伊朗认为力…"
