    "content": "新华社利雅得10月11日电 沙特阿拉伯、埃及、巴基斯坦和土耳其11日发布联合声明，强烈谴责也门胡塞武装袭击沙特，并要求该组织立即、无条件停止此类袭击。 沙特外交部在社交媒体上发布的这份联合声明说，胡塞武装的袭击侵犯沙特主权和领土完整，直接威胁沙特安全、稳定及平民安全，其行为还威胁到地区和国际和平与安全，该组织应对相应后果承担全部责任。四国要求胡塞武装立即、无条件停止袭击沙特。 声明还说，四国支持沙特依据《联合国宪章》和国际法采取合法措施对抗此类袭击，消除威胁源头，防止其再度发生。 据沙特主导的多国联军、沙特民航总局…"
