    "content": "新华社利雅得10月11日电 沙特阿拉伯主导的多国联军11日说，位于沙特首都利雅得的哈立德国王国际机场航站楼再遭袭击。沙特民航总局说，此次袭击造成人员受伤。 多国联军发言人图尔基·马利基当天在社交媒体上说，一枚不明弹体击中哈立德国王国际机场4号航站楼。防空系统在机场附近拦截并摧毁一枚导弹，袭击引发的火情正在处置。 新华社记者当天在利雅得听到一声巨响，并看到黑烟升起。 沙特民航总局在社交媒体上说，此次袭击造成人员受伤，正协调有关部门开展机场设施受损情况评估和安全检查。 也门胡塞武装同日发表声明说，过去24小时内对沙特境…"
