    "content": "新华社科威特城10月11日电（记者尹炣）萨那消息：也门胡塞武装11日说，过去24小时内，该组织使用导弹和无人机对沙特阿拉伯境内机场和能源设施实施4次军事行动。 胡塞武装军事发言人叶海亚·萨雷亚当天通过该组织控制的马西拉电视台发表声明说，此次行动使用了弹道导弹、巡航导弹和无人机，袭击目标包括位于沙特首都利雅得的哈立德国王国际机场、东部省达曼市附近的法赫德国王国际机场以及沙特阿美石油公司两处设施。 声明说，第一次行动从10日开始，分三波袭击哈立德国王国际机场，导致机场航班运行中断并迫使机场关闭。第二次行动针对位于沙特东…"
