    "content": "新华社安卡拉10月11日电（记者霍丹彤）土耳其外交部11日发表声明，谴责也门胡塞武装再次袭击沙特阿拉伯首都利雅得哈立德国王国际机场。 声明说，故意针对民用基础设施和无辜平民的袭击明显违反了国际法和人道主义原则。 声明呼吁立即停止威胁地区安全与稳定、损害国际社会和平努力的行为，并重申土耳其对沙特主权和领土完整的支持。 据沙特阿拉伯主导的多国联军声明，也门胡塞武装10日袭击了哈立德国王国际机场一座航站楼。沙特民航总局说，袭击造成12人死亡、309人受伤。 此前，沙特阿拉伯民航总局9日发表声明说，哈立德国王国际机场8日遭…"
