    "content": "新华社里斯本10月11日电（记者荀伟）2026世界超级摩托车锦标赛（WSBK）葡萄牙站WorldSSP组别次回合正赛11日在埃什托里尔赛道举行。中国摩托车制造商“张雪机车”的法国车手德比斯获得第三名，提前锁定年度车手亚军。 图为中国摩托车制造商“张雪机车”车队车手瓦伦丁·德比斯在本站比赛中。新华社发（卡洛斯·科斯塔摄） 本站比赛后，德比斯以291分继续位列车手积分榜第二，虽然落后“领头羊”阿雷纳斯73分，但领先第三名57分，在本赛季还剩一站比赛的情况下，已足够保证他获得亚军。 德比斯赛后对记者说，当天的次回合比赛受…"
