    "content": "新华社华盛顿10月11日电 乌克兰总统泽连斯基11日就美国总统特朗普有关乌克兰换总统的言论回应说，乌克兰选择哪位领导人应由其社会和人民决定。 泽连斯基在接受美国广播公司采访时说：“特朗普总统说乌克兰需要一位新总统。恕我直言，特朗普总统，选择哪位领导人，应由我们的社会、我们的人民决定。” 泽连斯基称，乌克兰处于战争状态，现在举行选举“真的很难”，且不安全，也不符合乌克兰宪法。“最关键的是，要有安全保障的基础设施，让民众有可能投票。” 泽连斯基还说，自己已告知特朗普团队，如果俄罗斯同意实行60天的全面停火，乌克兰可以举…"
